<?php
namespace App\Domain\WorkProcesses; use App\Models\WorkProcess; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; final class WorkProcessManager { public function save(array $data,?WorkProcess $item,int $userId):WorkProcess{return DB::transaction(function()use($data,$item,$userId){$item??=new WorkProcess;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)WorkProcess::max('display_order')+1;}else unset($data['status']);$item->fill($data)->save();$this->normalize();return $item;});} public function publish(WorkProcess $item):void{$this->requireContent($item);$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(WorkProcess $item,string $utc):void{$this->requireContent($item);$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(WorkProcess $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(WorkProcess $item):void{if(app(WorkProcessDependencyInspector::class)->inspect($item)['blocked'])throw ValidationException::withMessages(['work_process'=>'Resolve active references before archiving.']);$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(WorkProcess $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(WorkProcess $item,int $userId):WorkProcess{return DB::transaction(function()use($item,$userId){$copy=$item->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->title.=' (Copy)';$copy->slug=$this->uniqueSlug($item->slug.'-copy');$copy->status='draft';$copy->published_at=$copy->scheduled_for=$copy->archived_at=null;$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)WorkProcess::max('display_order')+1;$copy->save();$item->stages()->with('deliverables')->each(function($stage)use($copy){$new=$copy->stages()->create($stage->only($stage->getFillable()));$stage->deliverables->each(fn($deliverable)=>$new->deliverables()->create($deliverable->only($deliverable->getFillable())));});return $copy;});} public function move(WorkProcess $item,string $direction):void{DB::transaction(function()use($item,$direction){$peer=WorkProcess::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalize();});} public function uniqueSlug(string $base):string{$base=Str::slug(Str::lower($base))?:'work-process';$slug=$base;for($i=2;WorkProcess::where('slug',$slug)->exists();$i++)$slug=Str::limit($base,150,'')."-$i";return $slug;} private function normalize():void{WorkProcess::orderBy('display_order')->orderBy('id')->get()->each(fn($item,$i)=>$item->display_order===$i+1?null:$item->updateQuietly(['display_order'=>$i+1]));} private function requireContent(WorkProcess $item):void{if(!trim($item->title)||!trim($item->short_description)||!$item->stages()->where('is_active',true)->exists())throw ValidationException::withMessages(['work_process'=>'A title, short description, and active stage are required before publication.']);} }
